function parseObject(value) {
  if (value && typeof value === "object" && !Array.isArray(value)) return value;
  if (Array.isArray(value)) value = value.map((part) => typeof part === "string" ? part : (part?.text ?? part?.content ?? "")).join("\n");
  const text = String(value ?? "").trim();
  const candidates = [text];
  for (const match of text.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi)) candidates.push(match[1].trim());
  let depth = 0; let start = -1; let inString = false; let escaped = false;
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (inString) { if (escaped) escaped = false; else if (char === "\\") escaped = true; else if (char === "\"") inString = false; continue; }
    if (char === "\"") { inString = true; continue; }
    if (char === "{") { if (depth === 0) start = i; depth++; }
    else if (char === "}" && depth > 0) { depth--; if (depth === 0 && start >= 0) candidates.push(text.slice(start, i + 1)); }
  }
  for (let i = candidates.length - 1; i >= 0; i--) {
    try { const parsed = JSON.parse(candidates[i]); if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed; } catch {}
  }
  throw new Error("Nemotron response does not contain a valid JSON object");
}
const message = $json.choices?.[0]?.message;
const parsed = parseObject(message?.content ?? $json.text ?? $json.output ?? $json);
const detectedLanguage = String(parsed.detected_language ?? "").trim().toLowerCase();
const confidence = Number(parsed.confidence);
const evidence = String(parsed.evidence ?? "").trim();
if (!/^[a-z]{2,3}(?:-[a-z0-9]{2,8})?$/.test(detectedLanguage)) throw new Error("Invalid detected_language in Nemotron response");
if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) throw new Error("Invalid confidence in Nemotron response");
if (!["title", "description", "title_and_description", "insufficient"].includes(evidence)) throw new Error("Invalid evidence in Nemotron response");
return { json: { output: { detected_language: detectedLanguage, confidence, evidence } } };
